        throw new McpError(-32602, `session not found: ${session_id}`);
      }
      if (!store.has(key)) {
        throw new McpError(-32602, `key not found: ${key}`);
      }
      return { content: [{ type: 'text', text: store.get(key) }] };
    }
    default:
      throw new McpError(-32601, `unknown tool: ${name}`);
  }
}
